function mapOpp(s){const t=String(s||'').trim();return OPP_MAP[t]||t}
function asOpen(v){const list=(Array.isArray(v)?v:String(v||'').split(/[,|]/)).map(mapOpp).map(s=>s.trim()).filter(s=>opps.includes(s));return list.length? [...new Set(list)]:[opps[0]]}
function openList(p){return asOpen(p?.open)}
function tokenize(s){return [...new Set(String(s??'').toLowerCase().match(/[a-z]+/g)||[])].filter(w=>w.length>2&&!STOP.has(w))}
function overlapScore(need, field){const A=tokenize(need), B=tokenize(field);if(!A.length||!B.length)return 0;const hits=A.filter(w=>B.some(x=>x===w||x.includes(w)||w.includes(x)));return Math.round(100*hits.length/A.length)}
function relevanceBand(score){return score>=70?'Strong':score>=45?'Moderate':'Limited'}
function personHay(p){const projects=projectsFor(p.id).map(x=>[x.title,x.summary,x.methods,x.technologies,x.applications,x.research_area].join(' ')).join(' ');return `${p.topics||''} ${p.methods||''} ${p.skills||''} ${p.project||''} ${p.publication||''} ${p.bio||''} ${projects}`}
