function opportunityById(id){return (db.opportunities||[]).find(x=>x.id===id)}
function visibleToMatch(p){if(p.visibility==='Private')return false;if(p.visibility==='Limited')return db.role!=='Researcher';return p.visibility==='Public'}
function compatibleOpen(p,op){return openList(p).includes(op)}
function evidenceList(p){const items=[];if(p.publication)items.push({type:'Publication',title:p.publication});projectsFor(p.id).filter(x=>x.visibility!=='Private').forEach(x=>items.push({type:'Project',title:x.title,status:x.status}));if(!projectsFor(p.id).length&&p.project)items.push({type:'Project',title:p.project});return items}
function heuristicExtract(text){const t=String(text||'').toLowerCase();const pick=(arr)=>arr.filter(x=>t.includes(x.toLowerCase()));return{research_domains:pick(['Computer Vision','Artificial Intelligence','Materials science','Clean energy','Biotechnology','Robotics','Catalysis']),research_topics:pick(['Defect Detection','Visual Inspection','Anomaly Detection','Carbon capture','Battery recycling','Diagnostics','Robotics']),technical_methods:pick(['Image Classification','Anomaly Detection','Machine learning','Electrochemistry','Few-shot learning','Protein engineering']),technologies:pick(['Computer Vision','Biosensors','Polymers','Machine learning']),applications:pick(['Industrial inspection','Manufacturing','Healthcare','Energy','Robotics']),industries:pick(['Manufacturing','Energy','Healthcare','Robotics']),skills:pick(['Computer vision','Anomaly detection','Catalysis','Machine learning']),potential_opportunity_types:pick(opps)}}
