function migrate(data){
  const base=seed();
  const d=data&&typeof data==='object'?data:{};
  const people=(Array.isArray(d.people)?d.people:base.people).map(p=>{
    const next={department:'',location:'',skills:'',...p,open:asOpen(p.open),visibility:visibilities.includes(p.visibility)?p.visibility:'Public'};
    return next;
  });
  let projects=Array.isArray(d.projects)?d.projects.slice():[];
  if(!projects.length){
    projects=people.filter(p=>p.project).map(p=>({id:'proj-'+p.id,personId:p.id,title:p.project,summary:p.bio||'',problem:'',research_area:(p.topics||'').split(',')[0]||'',methods:p.methods||'',technologies:'',applications:'',status:'Active Research',visibility:p.visibility||'Public',publications:p.publication||''}));
  }
  const org={...base.org,...(d.org||{}),type:ORG_TYPE_MAP[d.org?.type]||d.org?.type||base.org.type};
  const out={
    ...base,
    ...d,
    people,
    projects,
    opportunities:Array.isArray(d.opportunities)&&d.opportunities.length?d.opportunities:base.opportunities,
    matches:Array.isArray(d.matches)?d.matches:[],
    savedPeople:Array.isArray(d.savedPeople)?d.savedPeople:[],
    savedOpportunities:Array.isArray(d.savedOpportunities)?d.savedOpportunities:[],
    posts:Array.isArray(d.posts)?d.posts:base.posts,
    saved:Array.isArray(d.saved)?d.saved:[],
    following:Array.isArray(d.following)?d.following:base.following,
    org,
    intros:Array.isArray(d.intros)?d.intros:[],
    messages:Array.isArray(d.messages)?d.messages:[],
    milestones:Array.isArray(d.milestones)?d.milestones:base.milestones,
    documents:Array.isArray(d.documents)?d.documents:base.documents,
    ledger:Array.isArray(d.ledger)?d.ledger:[],
    role:roles.includes(d.role)?d.role:'Organization',
    rolePicked:!!d.rolePicked,
    weights:{...SCORE_WEIGHTS,...(d.weights||{})},
    settings:{...defaultSettings(),...(d.settings||{}),apiKey:d.settings?.apiKey||''}
  };
  delete out.clean;
  return out;
}

