function completeness(p){const checks=[p.name,p.institution,p.topics,p.methods,p.publication,openList(p).length,projectsFor(p.id).length||p.project,p.bio];return Math.round(100*checks.filter(Boolean).length/checks.length)}
function matchCopy(){return db.role==='Investor'?'Potential technology/research relevance':'Match relevance'}

function scoreRecord(p,text,op,opp){
  const hay=personHay(p);
  const words=tokenize(text);
  const groups=[['clean','energy','carbon','fuel','catalyst','catalysis'],['battery','materials','polymer','recycling','sustainable','sustainability'],['vision','anomaly','inspection','defect','factory','industrial'],['biotechnology','biosensor','diagnostics','protein','biological'],['robotics','robotic','automation'],['ai','artificial','intelligence','machine','learning']];
  const hits=words.filter(w=>hay.toLowerCase().includes(w));
  const concepts=groups.filter(g=>g.some(w=>words.includes(w))&&g.some(w=>hay.toLowerCase().includes(w))).map(g=>g[0]);
  const raw=hits.length*3+concepts.length*2;
  const w=db.weights||SCORE_WEIGHTS;
  const topic_score=overlapScore(text,`${p.topics||''} ${p.publication||''} ${opp?.research_area||''}`);
  const method_score=overlapScore(`${text} ${opp?.desired_methods||''}`,`${p.methods||''} ${projectsFor(p.id).map(x=>x.methods).join(' ')}`);
  const technology_score=overlapScore(`${text} ${opp?.technical_requirements||''}`,`${p.skills||''} ${p.methods||''} ${projectsFor(p.id).map(x=>x.technologies).join(' ')}`);
  const application_score=overlapScore(`${text} ${opp?.industry||''}`,`${p.topics||''} ${p.project||''} ${projectsFor(p.id).map(x=>x.applications).join(' ')}`);
  const opportunity_score=compatibleOpen(p,op)?100:0;
  const ev=evidenceList(p);
  const evidence_score=Math.min(100,(p.publication?70:0)+(ev.some(x=>x.type==='Project')?30:0));
  const score=Math.round(topic_score*w.topic+method_score*w.method+technology_score*w.technical+application_score*w.application+opportunity_score*w.opportunity+evidence_score*w.evidence);
  const evidence=ev;
  const explanation=heuristicExplanation(p,op,hits,concepts,score,opp);
  return {p,hits,concepts,raw,score,score_version:SCORE_VERSION,topic_score,method_score,technology_score,application_score,opportunity_score,evidence_score,explanation,evidence,opportunity_id:opp?.id||null,status:'NEW'};
}
function heuristicExplanation(p,op,hits,concepts,score,opp){
  const overlap=hits.length?hits.slice(0,6).join(', '):(concepts.join(', ')||'limited overlapping terms');
  const fit=db.role==='Investor'||op==='Investment'?'The documented research appears relevant to the stated technology or research interest. It is not an investment recommendation.':`The research appears relevant to a ${op.toLowerCase()} based on the available information.`;
  return `This researcher works on topics that overlap with the stated need (${overlap}). ${fit} Relevance score ${score}/100 is an internal ranking signal, not a probability of success.`;
}
function scorePeople(text,op,opp){
  const opportunityType=mapOpp(op||opps[0]);
  return db.people.filter(p=>visibleToMatch(p)&&compatibleOpen(p,opportunityType)).map(p=>scoreRecord(p,text,opportunityType,opp)).filter(r=>r.raw>=3&&r.score>=20&&r.p.publication).sort((a,b)=>b.score-a.score||b.raw-a.raw).slice(0,8);
}
function scoreOpportunities(p){
  const profile=p||person(activeProfile)||db.people[0];
  if(!profile)return [];
  return (db.opportunities||[]).map(opp=>{
    const r=scoreRecord(profile,`${opp.title} ${opp.description} ${opp.research_area} ${opp.desired_methods} ${opp.technical_requirements}`,opp.opportunity_type,opp);
    return {...r,opportunity:opp};
  }).filter(r=>r.raw>=3&&r.score>=20&&compatibleOpen(profile,r.opportunity.opportunity_type)).sort((a,b)=>b.score-a.score);
}

function persistMatches(results,opp){
  db.matches=(results||[]).map(r=>({id:uid(),researcher_id:r.p.id,opportunity_id:opp?.id||r.opportunity_id,score:r.score,score_version:r.score_version,topic_score:r.topic_score,method_score:r.method_score,technology_score:r.technology_score,application_score:r.application_score,opportunity_score:r.opportunity_score,evidence_score:r.evidence_score,explanation:r.explanation,supporting_evidence:r.evidence,status:'NEW',created_at:new Date().toISOString()}));
}

