function view(){return ({home:homeView,people:peopleView,matches:matchesView,profile:profileView,explore:exploreView,settings:settingsView,dashboard:dashboardView,room:roomView,post:postView})[page]?.()||homeView()}

function postCard(p){const a=person(p.author);if(!a)return '';return `<article class="card"><div class="row between">${identity(a)}<button class="icon ${db.saved.includes(p.id)?'saved':''}" data-action="bookmark" data-id="${p.id}" aria-label="${db.saved.includes(p.id)?'Unsave':'Save'} post">${db.saved.includes(p.id)?'▣':'♧'}</button></div><h2>${esc(p.title)}</h2><p class="desc">${esc(p.body)}</p><div class="tags"><span class="tag green">✓ Research update</span><span class="tag">${esc(p.topic)}</span>${p.status==='Draft'?'<span class="tag gold">Draft</span>':''}</div><div class="card-foot"><button class="text" data-action="profile" data-id="${a.id}"><span class="badge-dot"></span>Meet the researcher →</button><div class="row"><button class="text" data-action="editpost" data-id="${p.id}">Edit</button><button class="text danger" data-action="deletepost" data-id="${p.id}">Delete</button></div></div></article>`}
function filteredPosts(){return db.posts.filter(p=>(tab!=='Saved'||db.saved.includes(p.id))&&(tab!=='Following'||db.following.includes(p.author))&&(filter==='All topics'||p.topic===filter)&&`${p.title} ${p.body} ${person(p.author)?.name}`.toLowerCase().includes(query.toLowerCase()))}
function homeView(){return heading('A little curiosity. A lot of possibility.','Your research, connected.','Discover ideas. Find your people. Move research forward.')+`${db.rolePicked?'':`<div class="panel"><div class="eyebrow">How will you use this workspace?</div><h2>Connect research with opportunity.</h2><p class="muted">Find researchers. Discover emerging research. Connect with industry.</p><div class="row wrap"><button class="primary" data-action="setrole" data-id="Researcher">I'm a Researcher</button><button data-action="setrole" data-id="Organization">I'm looking for research</button><button data-action="setrole" data-id="Investor">I'm an Investor</button></div></div>`}<div class="home-grid"><section><div class="hero"><div class="eyebrow"><span class="badge-dot"></span>From insight to impact</div><h2>Great research.<br>Real-world possibilities.</h2><p class="muted">Your next collaborator, industry partner,<br>or backer could be one idea away.</p><button class="text" data-page="matches">Find your next connection &nbsp; →</button><div class="hero-art" aria-hidden="true"><div class="orbit"></div><div class="art-leaf">${logo}</div><div class="art-paper">☰</div><div class="art-check">✓</div></div></div><div class="tabs">${['For you','Following','Saved'].map(t=>`<button class="${tab===t?'active':''}" data-action="feedtab" data-id="${t}">${t==='For you'?'✧ &nbsp; ':''}${t}</button>`).join('')}<span class="muted">● &nbsp; Curated, not endless</span></div><div class="toolbar"><input id="search" aria-label="Search research" placeholder="Search research, people, ideas…" value="${esc(query)}"><select id="topicfilter" aria-label="Filter topic">${options(['All topics',...topics],filter)}</select></div><div id="feed-results">${filteredPosts().map(postCard).join('')||empty('A little room for discovery.')}</div></section><section class="rightcol"><div class="panel"><div class="eyebrow">Make a little progress</div><h3 style="margin-top:15px">An idea worth sharing?</h3><p class="muted">Start a conversation with the people who can help it grow.</p><button class="primary" style="width:100%" data-page="post">＋ Share research</button></div><div class="panel"><div class="row between"><h3 style="margin:0">People to know</h3><span class="eyebrow">01—03</span></div>${db.people.slice(1,4).map(p=>`<button class="text" style="display:block;text-align:left" data-action="profile" data-id="${p.id}">${identity(p)}</button>`).join('')}<button class="text" data-page="people" style="color:var(--green)">Explore the community →</button></div><div class="panel" style="background:#faf3e3"><div class="eyebrow">${esc(db.role)} workspace</div><h3 style="margin-top:15px">Qualified connections, not just profiles.</h3><p class="muted" style="font-size:12px;margin-bottom:0">Match research to opportunity, then request an introduction.</p><button class="text" data-page="dashboard">Open dashboard →</button></div></section></div>`}

function peopleFiltered(){return db.people.filter(p=>`${p.name} ${p.institution} ${p.topics} ${p.methods} ${p.bio} ${p.skills||''}`.toLowerCase().includes(query.toLowerCase())&&(filter==='All topics'||p.topics.includes(filter)))}
function personCard(p){return `<article class="card">${identity(p)}<h3>${esc(p.role)}</h3><p class="muted">${esc(p.bio)}</p>${tags(p.topics)}<span class="tag green">${esc(openList(p)[0]||'')}</span><div class="card-foot"><button class="text" data-action="profile" data-id="${p.id}">View profile →</button><div class="row"><button class="text" data-action="saveperson" data-id="${p.id}">${(db.savedPeople||[]).includes(p.id)?'Saved ✓':'Save'}</button><button class="text" data-action="editperson" data-id="${p.id}">Edit</button><button class="text danger" data-action="deleteperson" data-id="${p.id}">Delete</button></div></div></article>`}
function peopleView(){return heading('The people behind the possibilities','Find your people.','A living directory. Add a person, change their story, or find a new collaborator.',`<button class="primary" style="margin-top:20px;white-space:nowrap" data-action="addperson">＋ Add person</button>`)+`<div class="toolbar"><input id="search" aria-label="Search people" placeholder="Search names, institutions, topics, or skills…" value="${esc(query)}"><select id="topicfilter" aria-label="Filter topic">${options(['All topics',...topics],filter)}</select></div><p class="muted" id="person-count">${peopleFiltered().length} demo profiles · Your edits are saved locally</p><div class="grid" id="people-results">${peopleFiltered().map(personCard).join('')||empty('No people found.')}</div>`}

function profileView(){const p=person(activeProfile)||db.people[0];if(!p)return heading('A new beginning','Your research story.','Start by adding your first researcher.')+'<button class="primary" data-action="addperson">Add person</button>';activeProfile=p.id;const plist=projectsFor(p.id);return heading('The person behind the possibilities','Your research story.','A little about you. A lot about what comes next.')+`<div class="home-grid"><section><div class="card profile-card"><div class="banner"></div><div class="profile-body"><div class="avatar profile-avatar">${initials(p.name)}</div><div class="tags"><span class="tag green">${p.verified?'✓ Demo verified':'Demo researcher'}</span><span class="tag gold">Open to opportunities</span><span class="tag">${esc(p.visibility)}</span></div><h2>${esc(p.name)}</h2><p class="muted">${esc(p.role)} · ${esc(p.institution)}${p.department?' · '+esc(p.department):''}</p><p class="muted">${esc(p.location||'')}</p><p class="muted">${esc(p.bio)}</p>${tags(p.topics)}<div class="row wrap"><button data-action="editperson" data-id="${p.id}">Edit profile</button><button class="primary" data-action="intro" data-id="${p.id}">Request introduction →</button><button data-action="follow" data-id="${p.id}">${db.following.includes(p.id)?'Following ✓':'Follow'}</button></div></div><div class="stats"><div class="stat">${db.posts.filter(x=>x.author===p.id).length}<small>Research posts</small></div><div class="stat">${db.intros.filter(x=>x.person===p.id&&x.status==='Accepted').length}<small>Connections</small></div><div class="stat">${plist.length}<small>Active projects</small></div></div></div><div class="row between"><h2>Current projects</h2><button class="small" data-action="addproject" data-id="${p.id}">＋ Add project</button></div>${plist.map(pr=>`<div class="card"><div class="row between"><span class="tag">${esc(pr.status)}</span><span class="tag">${esc(pr.visibility)}</span></div><h3>${esc(pr.title)}</h3><p class="muted">${esc(pr.summary)}</p><p class="muted">${esc(pr.methods)}</p><div class="row wrap"><button class="text" data-action="editproject" data-id="${pr.id}">Edit</button><button class="text danger" data-action="deleteproject" data-id="${pr.id}">Delete</button></div></div>`).join('')||`<div class="card"><h3>${esc(p.project||'No projects yet')}</h3><p class="muted">${esc(p.methods)}</p></div>`}<h2>Relevant work</h2><div class="card"><h3>${esc(p.publication||'No publication added')}</h3><p class="muted">Demonstration publication · User-provided evidence</p></div></section><section class="rightcol"><div class="panel"><h3>Open to possibility</h3>${tags(openList(p))}<p class="muted">Every introduction starts with your approval.</p></div><div class="panel"><h3>Profile completeness</h3><div class="stat">${completeness(p)}%<small>Demo checklist</small></div></div><div class="panel"><h3>Switch demo profile</h3><select id="switchprofile" aria-label="Switch profile">${db.people.map(x=>`<option value="${x.id}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></div></section></div>`}

function matchCards(){if(matchResults===null)return '<div class="notice">Try “sustainable battery recycling” or “computer vision for industrial quality inspection”.</div>';if(!matchResults.length)return empty('We couldn\'t find a strong match.','Tell us more about the technical method, application, or desired collaboration — or add a relevant public profile.');return `<p class="search-summary muted">${matchResults.length} ranked ${matchResults.length===1?'researcher':'researchers'} · ${esc(matchCopy())} is an internal ranking signal</p><div class="grid">${matchResults.map(r=>{const {p,score,explanation,evidence}=r;return `<div class="card">${identity(p)}<div class="score-pill"><span class="tag green">${esc(matchCopy())}: ${relevanceBand(score)}</span><span class="tag">${score}/100</span></div>${tags(p.topics)}<small>EVIDENCE · USER-PROVIDED</small>${(evidence||[]).map(ev=>`<h3 style="font-size:20px;margin:10px 0">${esc(ev.type)}: ${esc(ev.title)}</h3>`).join('')||`<h3 style="font-size:20px">${esc(p.publication)}</h3>`}<div class="match-why"><strong>Why this researcher may be relevant</strong><p style="margin:8px 0 0">${esc(explanation)}</p><p class="muted" style="margin:10px 0 0;font-size:12px">${esc(MATCH_DISCLAIMER)}</p></div><div class="card-foot"><button class="text" data-action="profile" data-id="${p.id}">View profile</button><div class="row"><button class="text" data-action="saveperson" data-id="${p.id}">Save</button><button class="primary small" data-action="intro" data-id="${p.id}">Request intro →</button></div></div></div>`}).join('')}</div>`}
function reverseCards(){const p=person(activeProfile)||db.people[0];if(!p)return empty('Add a researcher profile first.');const rows=scoreOpportunities(p);if(!rows.length)return empty('No strong opportunity matches yet.','Create an opportunity from Find researchers, or add more public research evidence.');return `<p class="search-summary muted">Opportunities for ${esc(p.name)} · Ranked from saved opportunity records</p><div class="grid">${rows.map(r=>`<div class="card"><span class="eyebrow">${esc(db.org.name)}</span><h3>${esc(r.opportunity.title)}</h3><p class="muted">${esc(r.opportunity.description)}</p><div class="score-pill"><span class="tag green">${relevanceBand(r.score)}</span><span class="tag">${r.score}/100</span></div><div class="match-why"><strong>Why you may be relevant</strong><p style="margin:8px 0 0">${esc(r.explanation)}</p></div><div class="card-foot"><button class="text" data-action="saveopp" data-id="${r.opportunity.id}">${(db.savedOpportunities||[]).includes(r.opportunity.id)?'Saved ✓':'Save'}</button><button class="primary small" data-action="interest" data-id="${r.opportunity.id}">Express interest →</button></div></div>`).join('')}</div>`}
function introCards(){return `<div class="notice">Review the request, then accept or decline. Contact details stay private until a connection is created. All activity stays inside this demo.</div>${db.intros.map(i=>`<div class="card"><div class="row between"><div><span class="eyebrow">${esc(i.org||db.org.name)} ${i.direction==='interest'?'←':'→'} ${esc(person(i.person)?.name||'Removed profile')}</span><h3>${esc(i.subject||i.opportunity)}</h3></div><span class="tag ${i.status==='Accepted'?'green':i.status==='Declined'?'gold':'gold'}">${esc(i.status)}</span></div><p style="white-space:pre-wrap">${esc(i.message)}</p><div class="card-foot"><small>${new Date(i.date).toLocaleDateString()}</small>${i.status==='Pending'?`<div class="row"><button data-action="decline" data-id="${i.id}">Decline</button><button class="primary" data-action="accept" data-id="${i.id}">Accept introduction</button></div>`:`<span>${i.status==='Accepted'?'You\'re connected · Continue in Collaboration':'Request closed'}</span>`}</div></div>`).join('')||empty('No introductions yet.','Find a researcher and review an introduction draft to get started.')}`}
function matchesView(){const current=opportunityById(activeOpportunityId);return heading('The right people. The right possibilities.','A meeting of minds.','Start with a need. Discover the expertise that could move it forward.')+`<div class="tabs">${['Find researchers','Opportunities for you','Introductions'].map(t=>`<button data-action="matchtab" data-id="${t}" class="${matchTab===t?'active':''}">${t}${t==='Introductions'?` <span class="count">${db.intros.length}</span>`:''}</button>`).join('')}</div>`+(matchTab==='Find researchers'?`<form id="matchform" class="panel"><label for="need-title">Opportunity title</label><input id="need-title" name="title" maxlength="160" value="${esc(current?.title||'')}" placeholder="Industrial visual inspection"><label for="need">Describe what you're looking for</label><textarea id="need" name="need" required minlength="8" placeholder="We are looking for researchers working on…">${esc(need||current?.description||'')}</textarea><div class="formgrid"><div><label for="opportunity">Opportunity type</label><select id="opportunity" name="opportunity">${options(opps,opportunity)}</select></div><div><label>Research area</label><input name="research_area" value="${esc(current?.research_area||'')}" placeholder="Computer vision"></div><div><label>Desired methods</label><input name="desired_methods" value="${esc(current?.desired_methods||'')}"></div><div><label>Industry</label><input name="industry" value="${esc(current?.industry||db.org.industry||'')}"></div></div><div class="actions"><button class="primary" type="submit">Save opportunity and find matches →</button></div><small style="display:block;margin-top:14px">${hasAi()?'Optional AI can extract structured fields and write explanations after ranking.':'Demo matching uses topics, methods, and evidence. Optional AI can be added in Settings.'}</small></form><div id="match-results">${matchCards()}</div>`:matchTab==='Opportunities for you'?reverseCards():introCards())}

function exploreView(){return heading('Follow your curiosity','Ideas don’t live in silos.','Explore the connections. Discover what’s next.')+`<div class="panel"><h2>The topic landscape</h2><p class="muted">Choose a topic to explore the people behind it.</p><div class="topicmap">${['Clean energy','Biotechnology','All topics','Materials science','Artificial intelligence'].map(t=>`<button data-action="topic" data-id="${t}">${t==='All topics'?'♧':'✧'}<br>${t}</button>`).join('')}</div></div><div class="hero" style="background:#fbf3e3"><div class="eyebrow">Looking for</div><h2>Research with real-world potential.</h2><p class="muted">A good question can be the start of something extraordinary.</p><button class="text" data-page="matches">Describe your research need →</button></div>`}

function dashboardView(){
  const me=person(activeProfile)||db.people[0];
  const pending=db.intros.filter(i=>i.status==='Pending');
  const accepted=db.intros.filter(i=>i.status==='Accepted');
  const recs=me?scoreOpportunities(me).slice(0,3):[];
  const orgStats=`<div class="dash-grid"><div class="stat-card"><div class="stat">${(db.opportunities||[]).length}<small>Active opportunities</small></div></div><div class="stat-card"><div class="stat">${(db.matches||[]).length}<small>Stored research matches</small></div></div><div class="stat-card"><div class="stat">${pending.length}<small>Introduction requests</small></div></div><div class="stat-card"><div class="stat">${accepted.length}<small>Connections</small></div></div></div>`;
  const researcherStats=`<div class="dash-grid"><div class="stat-card"><div class="stat">${me?completeness(me):0}%<small>Profile completeness</small></div></div><div class="stat-card"><div class="stat">${recs.length}<small>Opportunity recommendations</small></div></div><div class="stat-card"><div class="stat">${pending.filter(i=>i.person===me?.id).length}<small>Introduction requests</small></div></div><div class="stat-card"><div class="stat">${(db.savedOpportunities||[]).length}<small>Saved opportunities</small></div></div></div>`;
  const investorStats=`<div class="dash-grid"><div class="stat-card"><div class="stat">${(db.matches||[]).length}<small>Research matches</small></div></div><div class="stat-card"><div class="stat">${esc(db.org.research_interests||'Add technology areas')}<small>Technology areas</small></div></div><div class="stat-card"><div class="stat">${(db.savedPeople||[]).length}<small>Saved researchers</small></div></div><div class="stat-card"><div class="stat">${pending.length}<small>Introduction requests</small></div></div></div>`;
  return heading('Marketplace pulse','Your dashboard.','Track matches, introductions, and the research that created them — not just profile counts.')+(db.role==='Researcher'?researcherStats:db.role==='Investor'?investorStats:orgStats)+`<div class="panel"><h2>Next actions</h2>${pending.slice(0,3).map(i=>`<div class="listrow"><span>${esc(i.org||db.org.name)} · ${esc(i.opportunity)}</span><button data-action="notifications">Review</button></div>`).join('')||'<p class="muted">No pending introductions.</p>'}<div class="row wrap" style="margin-top:16px"><button class="primary" data-page="matches">Go to matches</button><button data-page="people">Browse researchers</button></div></div>${db.role==='Researcher'&&recs.length?`<div class="panel"><h2>Opportunities for you</h2>${recs.map(r=>`<div class="listrow"><div><strong>${esc(r.opportunity.title)}</strong><small style="display:block">${relevanceBand(r.score)} · ${r.score}/100</small></div><button data-action="matchtab" data-id="Opportunities for you">View</button></div>`).join('')}</div>`:''}${ (db.savedPeople||[]).length?`<div class="panel"><h2>Saved researchers</h2>${db.savedPeople.map(id=>person(id)).filter(Boolean).map(p=>`<div class="listrow">${identity(p)}<button data-action="profile" data-id="${p.id}">Open</button></div>`).join('')}</div>`:''}`
}

function settingsView(){return heading('Your industry workspace','Explore with intention.','Keep your organization profile and discovery preferences up to date.')+`<form id="roleform" class="panel"><h2>Workspace role</h2><p class="muted">This demo does not use accounts. The role only changes dashboards and match language.</p><label>I am a</label><select name="role">${options(roles,db.role)}</select><div class="actions"><button class="primary" type="submit">Save role</button></div></form><form id="orgform" class="panel"><h2>Your organization</h2><label>Organization name</label><input name="name" required value="${esc(db.org.name)}"><label>Organization type</label><select name="type">${options(orgTypes,db.org.type)}</select><label>Industry</label><input name="industry" value="${esc(db.org.industry||'')}"><label>Website</label><input name="website" value="${esc(db.org.website||'')}" placeholder="https://"><label>Locations</label><input name="locations" value="${esc(db.org.locations||'')}"><label>Research interests / technology areas</label><input name="research_interests" value="${esc(db.org.research_interests||'')}"><label>What are you exploring?</label><textarea name="description">${esc(db.org.description)}</textarea><div class="actions"><button class="primary" type="submit">Save organization</button></div></form><form id="aiform" class="panel"><h2>Optional AI</h2><p class="muted">Used only for extraction, match explanations, and outreach drafts. Leave the key empty to keep deterministic matching. The key stays in this browser and is stripped from JSON export. Do not use production secrets in this demo.</p><label>API base URL</label><input name="apiBase" value="${esc(db.settings.apiBase||'')}"><label>Model</label><input name="model" value="${esc(db.settings.model||'')}"><label>API key</label><input name="apiKey" type="password" value="${esc(db.settings.apiKey||'')}" autocomplete="off"><div class="actions"><button class="primary" type="submit">Save AI settings</button></div></form><div class="panel"><h2>Your demo data</h2><p class="muted">Export a backup before resetting. Browser data is specific to this device and site address.</p><div class="row wrap"><button data-action="export" type="button">Export JSON backup</button><label class="small" style="margin:0">Import JSON<input id="importfile" type="file" accept="application/json" style="margin-top:6px"></label><button data-action="reset" class="danger" type="button">Reset demo data</button></div></div>`}

function roomView(){return heading('Private room · Demo collaboration','Circular battery materials.','A shared place for the next chapter of your research.')+`<div class="tabs">${['Documents','Messages','Milestones','Ledger'].map(t=>`<button data-action="roomtab" data-id="${t}" class="${roomTab===t?'active':''}">${t}</button>`).join('')}</div><div class="panel">${roomTab==='Documents'?`<div class="row between"><h2>Versioned documents</h2><button data-action="adddoc">＋ Add</button></div>${db.documents.map(d=>`<div class="listrow"><div>▤ &nbsp; ${esc(d.title)}<small style="display:block">Version ${d.version} · Demo document</small></div><button data-action="editdoc" data-id="${d.id}">Open</button></div>`).join('')}`:roomTab==='Messages'?`<h2>A conversation in progress</h2>${db.messages.map(m=>`<div class="listrow"><div><strong>You</strong><p style="margin:4px 0;white-space:pre-wrap">${esc(m.text)}</p><small>${new Date(m.date).toLocaleString()}</small></div></div>`).join('')||'<p class="muted">Start the first conversation in this demo room.</p>'}<form id="messageform"><label>Message</label><textarea name="text" required placeholder="Share an update…"></textarea><div class="actions"><button class="primary">Send demo message</button></div></form>`:roomTab==='Milestones'?`<h2>Good ideas, in progress</h2>${db.milestones.map(m=>`<label class="listrow"><span><input type="checkbox" data-milestone="${m.id}" ${m.done?'checked':''}> ${esc(m.text)}</span><button type="button" class="text danger" data-action="deletemilestone" data-id="${m.id}">Remove</button></label>`).join('')}<form id="milestoneform"><label>New milestone</label><div class="row"><input name="text" required placeholder="What comes next?"><button>Add</button></div></form>`:`<h2>Activity ledger</h2>${db.ledger.slice().reverse().map(l=>`<div class="listrow"><span>${esc(l.text)}</span><small>${new Date(l.date).toLocaleString()}</small></div>`).join('')||'<p class="muted">Saved collaboration activity will appear here.</p>'}`}</div>`}
function postView(){return heading('A little sharing goes a long way','Share your research.','Tell your research story in plain language. Give your next collaborator a place to start.')+`<div class="panel">${postForm()}</div>`}
function postForm(p={}){return `<form id="postform" data-id="${p.id||''}"><label>Researcher</label><select name="author" required>${db.people.map(a=>`<option value="${a.id}" ${a.id===p.author?'selected':''}>${esc(a.name)}</option>`).join('')}</select><label>Title</label><input name="title" required maxlength="160" value="${esc(p.title)}" placeholder="An idea worth sharing…"><label>Research update</label><textarea name="body" required placeholder="What did you discover, and what comes next?">${esc(p.body)}</textarea><label>Topic</label><select name="topic">${options(topics,p.topic)}</select><label>Status</label><select name="status">${options(['Published','Draft'],p.status)}</select><div class="actions"><button class="primary" ${db.people.length?'':'disabled'}>Save research post</button></div></form>`}
function modal(html){const d=$('#modal');d.innerHTML=`<button class="icon close" data-action="close" aria-label="Close dialog">×</button>${html}`;d.showModal()}
function editPerson(id){const p=person(id)||{};modal(`<h2>${id?'Edit their story.':'A new connection.'}</h2><p class="muted">Create a demo researcher. Changes are saved in this browser.</p><div class="ip-warn">${esc(IP_WARN)}</div><form id="personform" data-id="${id||''}"><div class="formgrid">${[['name','Full name',true],['institution','Institution',true],['department','Department',false],['location','Location',false],['role','Role / title',true],['topics','Topics (comma separated)',true],['methods','Methods',false],['skills','Technical skills',false],['bio','Research summary',false],['publication','Publication / evidence title',true],['project','Current project title',false]].map(([k,l,req])=>`<div class="${['bio','publication','project','topics'].includes(k)?'full':''}"><label for="field-${k}">${l}${req?' *':''}</label>${k==='bio'?`<textarea id="field-${k}" name="${k}">${esc(p[k])}</textarea>`:`<input id="field-${k}" name="${k}" ${req?'required':''} maxlength="500" value="${esc(p[k])}">`}</div>`).join('')}<div class="full"><label>Open to</label>${checkboxes('open',opps,p.open)}</div><div><label for="field-visibility">Visibility</label><select id="field-visibility" name="visibility">${options(visibilities,p.visibility||'Public')}</select></div></div><label><input name="verified" type="checkbox" ${p.verified?'checked':''}> Demo verified badge (not institution verification)</label><div class="actions"><button type="button" data-action="close">Cancel</button><button class="primary">Save person</button></div></form>`)}
function editProject(id,personId){const pr=db.projects.find(x=>x.id===id)||{personId,status:'Active Research',visibility:'Public'};modal(`<h2>${id?'Edit project':'New research project'}</h2><div class="ip-warn">${esc(IP_WARN)}</div><form id="projectform" data-id="${id||''}" data-person="${pr.personId||personId}"><label>Project title</label><input name="title" required value="${esc(pr.title||'')}"><label>Short summary</label><textarea name="summary" required>${esc(pr.summary||'')}</textarea><label>Problem</label><textarea name="problem">${esc(pr.problem||'')}</textarea><div class="formgrid"><div><label>Research area</label><input name="research_area" value="${esc(pr.research_area||'')}"></div><div><label>Status</label><select name="status">${options(projectStatuses,pr.status)}</select></div><div class="full"><label>Methods</label><input name="methods" value="${esc(pr.methods||'')}"></div><div class="full"><label>Technologies</label><input name="technologies" value="${esc(pr.technologies||'')}"></div><div class="full"><label>Applications</label><input name="applications" value="${esc(pr.applications||'')}"></div><div><label>Visibility</label><select name="visibility">${options(visibilities,pr.visibility||'Public')}</select></div><div><label>Linked publication</label><input name="publications" value="${esc(pr.publications||'')}"></div></div><div class="actions"><button type="button" data-action="extractproject">Extract with AI if available</button><button class="primary">Save project</button></div></form>`)}
function confirmAction(title,body,action,id=''){modal(`<h2>${title}</h2><p class="muted">${body}</p><div class="actions"><button data-action="close">Cancel</button><button class="primary" data-action="${action}" data-id="${id}">Confirm</button></div>`)}
function log(text){db.ledger.push({text,date:new Date().toISOString()})}
function formOpen(f,v){if(typeof f.querySelectorAll==='function'){const checked=[...f.querySelectorAll('[name="open"]:checked')].map(i=>i.value);if(checked.length)return asOpen(checked)}return asOpen(v.open)}
function heuristicDraft(p,opp){const work=p.publication||p.project||'their documented research';const subj=`Potential ${ (opp?.opportunity_type||opportunity).toLowerCase()} on ${(p.topics||'').split(',')[0]||'your research'}`.trim();const body=`Hello ${p.name},\n\nYour work on “${work}” is documented in this workspace. ${db.org.name} is exploring ${need||opp?.description||p.topics.toLowerCase()} and would like to request an introduction.\n\nThis message uses only profile information available here. Would you be open to an introductory conversation?\n${db.org.name}`;return{subject:subj,body}}

async function aiChat(user){
  const base=String(db.settings.apiBase||'').replace(/\/$/,'');
  const res=await fetch(`${base}/chat/completions`,{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer '+db.settings.apiKey},body:JSON.stringify({model:db.settings.model||'gpt-4o-mini',temperature:0,response_format:{type:'json_object'},messages:[{role:'system',content:'Use only information provided in the input. Do not invent facts. If information is unavailable, return null or an empty list. Separate documented evidence from inference. Do not make decisions about hiring, investment, funding eligibility, or research quality. Return structured JSON.'},{role:'user',content:user}]})});
  if(!res.ok)throw new Error('AI request failed');
  const data=await res.json();
  return JSON.parse(data.choices[0].message.content);
}
async function enhanceMatches(results,opp){
  if(!hasAi()||typeof fetch!=='function'||!results?.length)return results;
  try{
    const out=await aiChat(`Explain potential research-to-industry matches. Do not invent qualifications. Do not claim guaranteed fit, investment quality, or hiring suitability. Return JSON {"explanations":[{"id":"...","text":"..."}]}. Opportunity: ${JSON.stringify({title:opp?.title,description:opp?.description,type:opp?.opportunity_type})}. Candidates: ${JSON.stringify(results.map(r=>({id:r.p.id,name:r.p.name,topics:r.p.topics,methods:r.p.methods,publication:r.p.publication,evidence:r.evidence,score:r.score})))}`);
    const map=Object.fromEntries((out.explanations||[]).map(x=>[x.id,x.text]));
    results.forEach(r=>{if(map[r.p.id])r.explanation=map[r.p.id]});
  }catch{toast('AI explanation unavailable. Showing evidence-based ranking instead.')}
  return results;
}
async function openIntroModal(p){
  const opp=opportunityById(activeOpportunityId);
  let draft=heuristicDraft(p,opp);
  if(hasAi()&&typeof fetch==='function'){
    try{
      const ai=await aiChat(`Draft a concise professional introduction message. Use only the supplied information. Mention the specific research/project that created the match. Do not exaggerate, claim previous communication, or invent company initiatives. Return JSON {"subject":"","body":""}. Sender org: ${db.org.name}. Recipient: ${p.name}. Opportunity: ${opp?.title||opportunity}. Need: ${need||opp?.description||''}. Evidence: ${p.publication||p.project}.`);
      if(ai.subject||ai.body)draft={subject:ai.subject||draft.subject,body:ai.body||draft.body};
    }catch{toast('AI draft unavailable. Showing an editable template.')}
  }
  modal(`<h2>A thoughtful introduction.</h2><p class="muted">From ${esc(db.org.name)} to ${esc(p.name)}. Review and edit before sending within the demo. AI never sends automatically.</p><form id="introform" data-id="${p.id}"><label>Opportunity type</label><select name="opportunity">${options(opps,opp?.opportunity_type||opportunity)}</select><label>Subject</label><input name="subject" required value="${esc(draft.subject)}"><label>AI draft · edit before send</label><textarea name="message" required style="min-height:190px">${esc(draft.body)}</textarea><label><input type="checkbox" required> I have reviewed this introduction.</label><div class="actions"><button class="primary">Send request →</button></div></form>`);
}

document.addEventListener('click',e=>{
  const b=e.target.closest('[data-page],[data-action]');if(!b)return;
  if(b.dataset.page){$('#modal').close();go(b.dataset.page);return}
  const {action:a,id}=b.dataset;const p=person(id);
  if(a==='close')$('#modal').close();
  else if(a==='menu')modal(`<h2>Your research workspace.</h2><p class="muted">A place for ideas and the people behind them.</p>${nav.map(([np,i,n])=>`<button style="display:block;width:100%;text-align:left;margin:7px 0" data-page="${np}">${i} &nbsp; ${n} →</button>`).join('')}<button style="width:100%" data-page="post">＋ Share research</button>`);
  else if(a==='notifications'){matchTab='Introductions';go('matches')}
  else if(a==='setrole'){db.role=id;db.rolePicked=true;if(id==='Investor'&&db.org.type==='Company')db.org.type='VC';persist();render();toast('Workspace role updated')}
  else if(a==='addperson'||a==='editperson')editPerson(id);
  else if(a==='profile'){activeProfile=id;go('profile')}
  else if(a==='deleteperson')confirmAction('Delete this person?',`Remove ${esc(p.name)} and their posts, projects, and introductions from the demo?`,'confirmdeleteperson',id);
  else if(a==='confirmdeleteperson'){db.people=db.people.filter(x=>x.id!==id);db.posts=db.posts.filter(x=>x.author!==id);db.intros=db.intros.filter(x=>x.person!==id);db.projects=db.projects.filter(x=>x.personId!==id);db.savedPeople=(db.savedPeople||[]).filter(x=>x!==id);matchResults=null;persist();$('#modal').close();render();toast('Person deleted')}
  else if(a==='feedtab'){tab=id;render()}
  else if(a==='bookmark'){db.saved=db.saved.includes(id)?db.saved.filter(x=>x!==id):[...db.saved,id];persist();render();toast(db.saved.includes(id)?'Saved to your collection':'Removed from saved')}
  else if(a==='saveperson'){db.savedPeople=db.savedPeople.includes(id)?db.savedPeople.filter(x=>x!==id):[...db.savedPeople,id];persist();render();toast(db.savedPeople.includes(id)?'Researcher saved':'Removed from saved researchers')}
  else if(a==='saveopp'){db.savedOpportunities=db.savedOpportunities.includes(id)?db.savedOpportunities.filter(x=>x!==id):[...db.savedOpportunities,id];persist();render()}
  else if(a==='follow'){db.following=db.following.includes(id)?db.following.filter(x=>x!==id):[...db.following,id];persist();render()}
  else if(a==='editpost')modal('<h2>Edit your research.</h2>'+postForm(db.posts.find(x=>x.id===id)));
  else if(a==='deletepost')confirmAction('Delete this research post?','This removes the post from the demo feed.','confirmdeletepost',id);
  else if(a==='confirmdeletepost'){db.posts=db.posts.filter(x=>x.id!==id);persist();$('#modal').close();render();toast('Post deleted')}
  else if(a==='matchtab'){matchTab=id;if(page!=='matches')go('matches');else render()}
  else if(a==='topic'){page='people';filter=id;query='';render();window.scrollTo(0,0)}
  else if(a==='intro')openIntroModal(p);
  else if(a==='interest'){const opp=opportunityById(id)||db.opportunities[0];const me=person(activeProfile)||db.people[0];if(!me||!opp)return;db.intros.unshift({id:uid(),person:me.id,org:db.org.name,opportunity:opp.opportunity_type,opportunity_id:opp.id,subject:`Interest in ${opp.title}`,message:`${me.name} expressed interest in “${opp.title}” because of documented work on ${me.publication||me.project}.`,status:'Pending',direction:'interest',date:new Date().toISOString()});persist();matchTab='Introductions';go('matches');toast('Interest sent. Review it in Introductions.')}
  else if(a==='accept'||a==='decline'){const item=db.intros.find(x=>x.id===id);item.status=a==='accept'?'Accepted':'Declined';item.responded_at=new Date().toISOString();log(`Introduction ${item.status.toLowerCase()}`);persist();render();toast(a==='accept'?'You\'re connected. Open Collaboration to continue.':'Introduction declined')}
  else if(a==='roomtab'){roomTab=id;render()}
  else if(a==='adddoc'||a==='editdoc'){const d=db.documents.find(x=>x.id===id)||{};modal(`<h2>${id?'Edit document':'New document'}</h2><form id="docform" data-id="${id||''}"><label>Title</label><input name="title" value="${esc(d.title)}" required><label>Contents</label><textarea name="body" required>${esc(d.body)}</textarea><div class="actions"><button class="primary">Save version</button></div></form>`)}
  else if(a==='deletemilestone'){db.milestones=db.milestones.filter(x=>x.id!==id);log('Milestone removed');persist();render()}
  else if(a==='addproject')editProject('',id);
  else if(a==='editproject')editProject(id);
  else if(a==='deleteproject'){db.projects=db.projects.filter(x=>x.id!==id);persist();render();toast('Project deleted')}
  else if(a==='extractproject'){const f=$('#projectform');if(!f)return;const v=Object.fromEntries(new FormData(f));const extracted=heuristicExtract(`${v.title} ${v.summary} ${v.problem} ${v.methods}`);if(hasAi()&&typeof fetch==='function'){aiChat(`Extract structured research fields from this project. Do not invent. Return JSON with arrays research_domains, research_topics, technical_methods, technologies, applications, industries, skills, potential_opportunity_types. Input: ${JSON.stringify(v)}`).then(ex=>{f.elements.methods.value=f.elements.methods.value||(ex.technical_methods||[]).join(', ');f.elements.technologies.value=f.elements.technologies.value||(ex.technologies||[]).join(', ');f.elements.applications.value=f.elements.applications.value||(ex.applications||[]).join(', ');toast('Extracted fields added where empty')}).catch(()=>toast('AI extraction failed'))}else{if(!f.elements.methods.value)f.elements.methods.value=(extracted.technical_methods||[]).join(', ');if(!f.elements.technologies.value)f.elements.technologies.value=(extracted.technologies||[]).join(', ');if(!f.elements.applications.value)f.elements.applications.value=(extracted.applications||[]).join(', ');toast('Heuristic extraction applied where fields were empty')}}
  else if(a==='export'){const blob=new Blob([JSON.stringify(exportableDb(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='researchbridge-demo-backup.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Demo data exported')}
  else if(a==='reset')confirmAction('Start fresh?','This replaces all local edits with the original demo dataset. Export a backup first if needed.','confirmreset');
  else if(a==='confirmreset'){db=migrate(seed());matchResults=null;activeProfile='alex';activeOpportunityId='opp-cv';persist();$('#modal').close();go('home');toast('Demo reset')}
});
document.addEventListener('input',e=>{if(e.target.id==='search'){query=e.target.value;updateResults()}});
function updateResults(){if(page==='people'){$('#people-results').innerHTML=peopleFiltered().map(personCard).join('')||empty('No people found.');$('#person-count').textContent=`${peopleFiltered().length} demo profiles · Your edits are saved locally`}else if(page==='home')$('#feed-results').innerHTML=filteredPosts().map(postCard).join('')||empty('No research found.')}
document.addEventListener('change',e=>{
  if(e.target.id==='topicfilter'){filter=e.target.value;updateResults()}
  if(e.target.id==='switchprofile'){activeProfile=e.target.value;render()}
  if(e.target.dataset.milestone){const m=db.milestones.find(x=>x.id===e.target.dataset.milestone);m.done=e.target.checked;log(`${m.done?'Completed':'Reopened'} milestone: ${m.text}`);persist();render()}
  if(e.target.id==='importfile'&&e.target.files?.[0]){const file=e.target.files[0];const reader=new FileReader();reader.onload=()=>{try{db=migrate(JSON.parse(reader.result));matchResults=null;persist();render();toast('Demo data imported')}catch{toast('Import failed. Use a ResearchBridge JSON backup.')}};reader.readAsText(file)}
});
document.addEventListener('submit',e=>{
  e.preventDefault();
  const f=e.target,v=Object.fromEntries(new FormData(f));
  Object.keys(v).forEach(k=>v[k]=typeof v[k]==='string'?v[k].trim():v[k]);
  const id=f.dataset.id;
  if(f.id==='personform'){
    const value={...person(id)||{},...v,open:formOpen(f,v),verified:!!f.elements.verified?.checked,id:id||uid()};
    delete value.dataset;
    if(id)db.people=db.people.map(p=>p.id===id?value:p);else db.people.unshift(value);
    matchResults=null;persist();$('#modal').close();render();toast('Person saved');
  }else if(f.id==='projectform'){
    const personId=f.dataset.person;const value={...v,id:id||uid(),personId};
    if(id)db.projects=db.projects.map(p=>p.id===id?{...p,...value}:p);else db.projects.unshift(value);
    const owner=person(personId);if(owner)owner.project=value.title;
    persist();$('#modal').close();render();toast('Project saved');
  }else if(f.id==='postform'){const value={...v,id:id||uid()};if(id)db.posts=db.posts.map(p=>p.id===id?value:p);else db.posts.unshift(value);persist();$('#modal').close();go('home');toast('Research post saved')}
  else if(f.id==='orgform'){db.org={...db.org,...v};persist();toast('Organization saved')}
  else if(f.id==='roleform'){db.role=v.role;db.rolePicked=true;persist();render();toast('Workspace role updated')}
  else if(f.id==='aiform'){db.settings={...db.settings,...v};persist();toast('AI settings saved')}
  else if(f.id==='matchform'){
    need=v.need;opportunity=mapOpp(v.opportunity);
    const structured=heuristicExtract(`${v.title} ${v.need} ${v.research_area} ${v.desired_methods}`);
    const opp={id:uid(),title:v.title||v.need.slice(0,80),description:v.need,opportunity_type:opportunity,research_area:v.research_area||'',technical_requirements:v.desired_methods||'',desired_methods:v.desired_methods||'',industry:v.industry||db.org.industry||'',stage:'Exploration',location:db.org.locations||'',remote_allowed:'Yes',engagement_type:opportunity,structured};
    db.opportunities.unshift(opp);activeOpportunityId=opp.id;
    const button=typeof f.querySelector==='function'&&(f.querySelector('button[type="submit"]')||f.querySelector('button'));
    if(button){button.disabled=true;button.textContent='Finding connections…'}
    const finish=results=>{matchResults=results;persistMatches(results,opp);persist();render()};
    const ranked=scorePeople(need,opportunity,opp);
    if(hasAi()&&typeof fetch==='function'){
      aiChat(`Extract structured opportunity requirements. Do not invent. Return JSON with arrays research_domains, research_topics, technical_methods, technologies, industries and string opportunity_type. Input: ${JSON.stringify({title:opp.title,description:opp.description})}`).then(ex=>{opp.structured=ex;return enhanceMatches(ranked,opp)}).then(finish).catch(()=>finish(ranked));
    }else setTimeout(()=>finish(ranked),450);
  }else if(f.id==='introform'){db.intros.unshift({id:uid(),person:id,org:db.org.name,...v,opportunity_id:activeOpportunityId,status:'Pending',direction:'request',date:new Date().toISOString()});persist();$('#modal').close();matchTab='Introductions';go('matches');toast('Request sent. Accept or decline as the researcher.')}
  else if(f.id==='messageform'){db.messages.push({...v,date:new Date().toISOString()});log('Message added to demo room');persist();render();toast('Demo message saved')}
  else if(f.id==='milestoneform'){db.milestones.push({id:uid(),text:v.text,done:false});log('Milestone added: '+v.text);persist();render()}
  else if(f.id==='docform'){if(id){const d=db.documents.find(x=>x.id===id);Object.assign(d,v,{version:d.version+1})}else db.documents.push({id:uid(),...v,version:1});log('Document saved: '+v.title);persist();$('#modal').close();render();toast('Document version saved')}
});
render();
